function submitExam(){if(answers.some(a=>a===null)){toast('جاوب كل الأسئلة قبل إنهاء الاختبار.','warning');return;}let score=0;currentLesson.q.forEach((q,i)=>{if(answers[i]===q[3])score++;});const p=pct(score,15),passed=p>=APP.passPercent;const ex={...currentExam,finishedAt:new Date().toISOString(),score,total:15,percentage:p,passed,answers:[...answers],correctAnswers:currentLesson.q.map(q=>q[3])};state.exams.push(ex);lastExam=ex;if(passed){const i=indexOfLesson(currentLesson.id);if(!state.completedLessons.includes(currentLesson.id))state.completedLessons.push(currentLesson.id);state.lessonProgress[currentLesson.id]=100;if(i<10)state.unlockedLessons=Math.max(state.unlockedLessons,i+2);}else state.lessonProgress[currentLesson.id]=Math.min(64,Number(state.lessonProgress[currentLesson.id]||64));save();updateAchievements();renderResult(ex);showScreen('examResultScreen');}
function renderResult(ex){$('resultIcon').textContent=ex.passed?'🎉':'📚';$('resultTitle').textContent=ex.passed?'أحسنت! اجتزت الاختبار':'لسه محتاج شوية مذاكرة';$('resultScore').textContent=`${ex.score} / ${ex.total}`;$('resultPercentage').textContent=ex.percentage+'%';$('resultMessage').textContent=ex.passed?(ex.percentage>=85?'إيه الحلاوة دي! 🔥 ممتاز جدًا.':'ممتاز! 👏 حققت 65% وفتحنا لك الدرس التالي.'):`جبت ${ex.percentage}%، والمطلوب ${APP.passPercent}% على الأقل. راجع الدرس وحاول مرة أخرى.`;$('nextLessonButton').style.display=ex.passed&&indexOfLesson(ex.lessonId)<10?'':'none';}
